import numpy as np

def bm_path(n, T, seed):
    """W at n + 1 equal times on [0, T], W_0 = 0."""
    rng = np.random.default_rng(seed)
    dW = rng.standard_normal(n) * np.sqrt(T / n)
    return np.concatenate([[0.0], np.cumsum(dW)])

def increment_cov(paths, s_idx, t_idx):
    """Sample covariance of two columns of paths."""
    x, y = paths[:, s_idx], paths[:, t_idx]
    return float(np.cov(x, y)[0, 1])    # divides by n - 1

