import numpy as np

def many_paths(n_paths, n, T, seed):
    rng = np.random.default_rng(seed)
    dW = rng.standard_normal((n_paths, n)) * np.sqrt(T / n)
    return np.hstack([np.zeros((n_paths, 1)), np.cumsum(dW, axis=1)])
